/**
 * Node type registry. Core registers the built-in node types; plugins can add
 * custom ones or override serialization for built-ins (ADR-0004).
 */
import { escapeHtml } from '../utils/html';
export function createNodeRegistry() {
  const definitions = new Map();
  return {
    register(definition) {
      definitions.set(definition.type, definition);
      return () => {
        if (definitions.get(definition.type) === definition) definitions.delete(definition.type);
      };
    },
    get(type) {
      return definitions.get(type);
    },
    has(type) {
      return definitions.has(type);
    },
    list() {
      return [...definitions.values()];
    },
    clear() {
      definitions.clear();
    }
  };
}
// ---------------------------------------------------------------------------
// Built-in definitions
// ---------------------------------------------------------------------------
const as = node => node;
export const TEXT_NODE_DEFINITION = {
  type: 'text',
  isAtomic: false,
  toText: node => as(node).text,
  toMarkdown: node => as(node).text,
  toHtml: node => escapeHtml(as(node).text).replace(/\n/g, '<br>'),
  toDisplay: node => as(node).text
};
export const MENTION_NODE_DEFINITION = {
  type: 'mention',
  isAtomic: true,
  toText: node => `@${as(node).label}`,
  toMarkdown: node => `[@${as(node).label}](mention:${as(node).id})`,
  toHtml: node => `<span data-aic-node="mention" data-aic-id="${escapeHtml(as(node).id)}">@${escapeHtml(as(node).label)}</span>`,
  toDisplay: node => `@${as(node).label}`
};
export const COMMAND_NODE_DEFINITION = {
  type: 'command',
  isAtomic: true,
  toText: node => `/${as(node).label}`,
  toMarkdown: node => `[/${as(node).label}](command:${as(node).id})`,
  toHtml: node => `<span data-aic-node="command" data-aic-id="${escapeHtml(as(node).id)}">/${escapeHtml(as(node).label)}</span>`,
  toDisplay: node => `/${as(node).label}`
};
export const VARIABLE_NODE_DEFINITION = {
  type: 'variable',
  isAtomic: true,
  toText: node => `{{${as(node).name}}}`,
  toMarkdown: node => `{{${as(node).name}}}`,
  toHtml: node => `<span data-aic-node="variable" data-aic-name="${escapeHtml(as(node).name)}">{{${escapeHtml(as(node).name)}}}</span>`,
  toDisplay: node => `{{${as(node).name}}}`
};
export const ATTACHMENT_NODE_DEFINITION = {
  type: 'attachment',
  isAtomic: true,
  toText: node => as(node).name,
  toMarkdown: node => `[${as(node).name}](attachment:${as(node).id})`,
  toHtml: node => `<span data-aic-node="attachment" data-aic-id="${escapeHtml(as(node).id)}" data-aic-mime="${escapeHtml(as(node).mimeType)}">${escapeHtml(as(node).name)}</span>`,
  toDisplay: node => as(node).name
};
export const CUSTOM_NODE_DEFINITION = {
  type: 'custom',
  isAtomic: true,
  toText: node => JSON.stringify(as(node).data),
  toMarkdown: node => escapeHtml(JSON.stringify(as(node).data)),
  toHtml: node => `<span data-aic-node="custom" data-aic-plugin="${escapeHtml(as(node).plugin)}" data-aic-type="${escapeHtml(as(node).nodeType)}" data-aic-data="${escapeHtml(JSON.stringify(as(node).data))}">${escapeHtml(String(as(node).data ?? ''))}</span>`,
  toDisplay: node => String(as(node).data ?? '')
};
/** Registry pre-loaded with all built-in node types. */
export function createDefaultNodeRegistry() {
  const registry = createNodeRegistry();
  registry.register(TEXT_NODE_DEFINITION);
  registry.register(MENTION_NODE_DEFINITION);
  registry.register(COMMAND_NODE_DEFINITION);
  registry.register(VARIABLE_NODE_DEFINITION);
  registry.register(ATTACHMENT_NODE_DEFINITION);
  registry.register(CUSTOM_NODE_DEFINITION);
  return registry;
}
